private boolean allTAMRebateDateDateRangeLimitedUnderHeaderDateRange()
{
    TAMRebateDate  rebateDate;
    TAMRebateTable rebateTable;

    select firstonly RecId from rebateDate
        where rebateDate.RebateFromDate < this.RebateFromDate 
           || rebateDate.RebateToDate > this.RebateToDate
        exists join rebateTable
            where rebateTable.RebateId == rebateDate.RebateId
               && rebateTable.RebateDeal == this.RecId;

    return !rebateDate;
}

public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(null, this.ModuleInventCustVend, true))
    {
        if (this.RebateReconciliation == TAMRebateReconciliation::Deal)
        {
            if (this.RebateFromDate == dateNull())
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:FieldMustBeSpecified", fieldPName(TAMRebateDeal, RebateFromDate)));
            }

            if (this.RebateToDate == dateNull())
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:FieldMustBeSpecified", fieldPName(TAMRebateDeal, RebateToDate)));
            }

            if (this.orig().RebateFromDate != this.RebateFromDate || this.orig().RebateToDate != this.RebateToDate)
            {
                if (!this.allTAMRebateDateDateRangeLimitedUnderHeaderDateRange())
                {
                    ret = checkFailed("@GlobalUnifiedPricing:RebateDateRangeOnHeaderShouldIncludLines");
                }
            }
        }

        if (this.RebateReconciliation == TAMRebateReconciliation::Line && !this.RebatePostingId)
        {
            ret = checkFailed(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateDeal, RebatePostingId)));
        }

        if (this.RebateAgreementType)
        {
            if (this.RebateCompanyId && CompanyInfo::findDataArea(this.RebateCompanyId).RecId)
            {
                GUPRebateAgreementType rebateAgreementType;

                changecompany(this.RebateCompanyId)
                {
                    rebateAgreementType = GUPRebateAgreementType::findByName(this.RebateAgreementType);
                }

                if (!rebateAgreementType.RecId)
                {
                    ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPRebateRebateAgreementTypeIsNotValid", this.RebateAgreementType, this.RebateCompanyId));
                }
            }
            else
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPRebateCompanyIsNotValid");
            }
        }

        ret = ret && this.validateRecipientWithPostingProfile();
    }

    return ret;
}

private boolean validateRecipientWithPostingProfile()
{
    boolean ret = true;

    if (this.Recipient && this.RebateReconciliation == TAMRebateReconciliation::Deal && this.RebatePostingId)
    {
        TAMRebatePosting rebatePosting = TAMRebatePosting::find(this.RebatePostingId, this.ModuleInventCustVend);
        if (rebatePosting.RebatePostingType != TAMRebatePostingAccountType::CustVend)
        {
            ret = checkFailed("@GlobalUnifiedPricing:RebatePostingTypeMustBeCustVend");
        }
    }

    return ret;
}
